/** Typed view of src/data/roster.json (generated by tools/data/import_pokedex.py). Pure data, shared by the engine, the save checks and the UI. */
import data from '../data/roster.json' with {type:'json'};
import bosses from '../data/boss.json' with {type:'json'};
export type KitMove={move:string;pp:number};
export type Species={id:string;dex:string;name:string;learnsetGen:number;starter?:boolean;types?:string[];maxHp:number;kit:KitMove[];learnable:KitMove[];availability?:'暂不出场';evoLevel:number;prevo?:string;evos?:string[];legendary:boolean};
export const SPECIES:Record<string,Species>=Object.fromEntries((data.species as Species[]).map(s=>[s.id,s]));
/** The species the player may pick as the main character (stage 7.1: generation 1-3 starters), in roster order. */
export const STARTER_IDS:string[]=(data.species as Species[]).filter(s=>s.starter).map(s=>s.id);
export const speciesOf=(id:string):Species|undefined=>Object.prototype.hasOwnProperty.call(SPECIES,id)?SPECIES[id]:undefined;
/**
 * 6.5 technique machines (workable candidates): the three moves that fill the "pin" and "reposition" gaps found in 6.2. A machine teaches one move to a compatible species.
 * 7.3 adds four more (dragontail, helpinghand, mudslap, terablast). `LEGACY_TM_MOVES` is what runs without the boss mark still draw from; `TM_MOVES` is the
 * seven-entry boss pool introduced in 7.3. Draws are `floor(r * length)`, so lengthening either old list would change what an old save's seed means.
 */
export const LEGACY_TM_MOVES=['protect','whirlwind','roar'] as const;
export const TM_MOVES=['protect','whirlwind','roar','dragontail','helpinghand','mudslap','terablast'] as const;
/** The 7.7b boss pool; only a new departure marked with tmPool:3 draws from these ten moves. */
export const TM_MOVES_V3=[...TM_MOVES,'quickguard','reflect','lightscreen'] as const;
/** All moves which can appear in the warehouse and pass legality checks. */
export const ALL_TM_MOVES=TM_MOVES_V3;
/** Missing tmPool preserves old saves: ordinary runs use three, old boss runs seven, new marked boss runs ten. */
export const tmPool=(d?:{boss?:boolean;tmPool?:3}|null):readonly string[]=>d?.boss?(d.tmPool===3?TM_MOVES_V3:TM_MOVES):LEGACY_TM_MOVES;
export type BossTraits={levelBonus:number;hpMultiplier:number;canMove:boolean;canBeBlownAway:boolean};
export const BOSS_CONFIG:Record<string,BossTraits>=bosses.bosses;
/** Bosses share the ordinary roster; recruited partners do not inherit boss traits. */
export const BOSS_SPECIES:Record<string,string>=Object.fromEntries(Object.keys(BOSS_CONFIG).map(id=>[id,SPECIES[id].dex]));
export const speciesMaxHp=(id:string,level:number,multiplier=1)=>Math.max(1,Math.round((SPECIES[id].maxHp+Math.max(0,level-5))*multiplier));
/** The move and its max PP from the roster's learnable list, or undefined when the species cannot learn it. */
export function learnableMove(speciesId:string,move:string):KitMove|undefined {
  const sp=speciesOf(speciesId);
  const m=sp?.learnable.find(l=>l.move===move);return m?{move:m.move,pp:m.pp}:undefined;
}
